{
  "items": [
    {
      "name": "Finsupp.le_weight",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} (w : σ → ℕ) {s : σ}, w s ≠ 0 → ∀ (f : σ →₀ ℕ), f s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "Finsupp.le_degree",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_5} [inst : AddCommMonoid R] [inst_1 : PartialOrder R] [CanonicallyOrderedAdd R] (s : σ)\n  (f : σ →₀ R), f s ≤ Finsupp.degree f"
    },
    {
      "name": "Finsupp.degree",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_4} → [inst : AddCommMonoid R] → (σ →₀ R) →+ R"
    },
    {
      "name": "Finsupp.support_mono",
      "module_name": "Mathlib.Data.Finsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [CanonicallyOrderedAdd α]\n  {f g : ι →₀ α}, f ≤ g → f.support ⊆ g.support"
    },
    {
      "name": "Finsupp.support_monotone",
      "module_name": "Mathlib.Data.Finsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [CanonicallyOrderedAdd α],\n  Monotone Finsupp.support"
    },
    {
      "name": "Finsupp.weight_apply",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (f : σ →₀ R), (Finsupp.weight w) f = f.sum fun i c => c • w i"
    },
    {
      "name": "Finsupp.degree_apply",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_4} [inst : AddCommMonoid R] (d : σ →₀ R), Finsupp.degree d = ∑ i ∈ d.support, d i"
    },
    {
      "name": "MvPolynomial.le_weightedTotalDegree",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  [inst_2 : SemilatticeSup M] [inst_3 : OrderBot M] (w : σ → M) {φ : MvPolynomial σ R} {d : σ →₀ ℕ},\n  d ∈ φ.support → (Finsupp.weight w) d ≤ MvPolynomial.weightedTotalDegree w φ"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero'",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    },
    {
      "name": "Finsupp.finite_of_nat_weight_le",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} [Finite σ] (w : σ → ℕ), (∀ (x : σ), w x ≠ 0) → ∀ (n : ℕ), {d | (Finsupp.weight w) d ≤ n}.Finite"
    }
  ]
}
